const WhereResearchBegins: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  const phaseBOpacity = interpolate(frame, [75, 100],  [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const phaseCOpacity = interpolate(frame, [152, 177], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });

  return (
    <AbsoluteFill style={{ fontFamily: "'Inter', sans-serif" }}>
      <Background />

      {/* Hashtag node web — no central node, just the surrounding tags */}
      <AbsoluteFill>
        {RESEARCH_NODES.map((node, i) => {
          const nodeP = spring({ frame, fps, delay: node.delay, config: { damping: 200 } });
          // Draw connection lines between adjacent nodes instead of to a center
          const nextNode = RESEARCH_NODES[(i + 1) % RESEARCH_NODES.length];
          const dx = nextNode.x - node.x;
          const dy = nextNode.y - node.y;
          const len = Math.sqrt(dx * dx + dy * dy);
          const angle = Math.atan2(dy, dx) * (180 / Math.PI);
          return (
            <React.Fragment key={i}>
              {/* Connection line to next node */}
              <div
                style={{
                  position: "absolute",
                  left: node.x,
                  top: node.y,
                  width: len * nodeP,
                  height: 2,
                  backgroundColor: `${node.color}30`,
                  transformOrigin: "0 50%",
                  transform: `rotate(${angle}deg)`,
                  opacity: nodeP * 0.5,
                }}
              />
              {/* Hashtag label */}
              <div
                style={{
                  position: "absolute",
                  left: node.x,
                  top: node.y,
                  transform: `translate(-50%, -50%) scale(${interpolate(nodeP, [0, 1], [0.3, 1])})`,
                  opacity: nodeP,
                  fontSize: node.size,
                  fontWeight: 700,
                  color: node.color,
                  whiteSpace: "nowrap",
                  textShadow: `0 0 40px ${node.color}55`,
                }}
              >
                {node.label}
              </div>
            </React.Fragment>
          );
        })}
      </AbsoluteFill>

      {/* USE_CHIPS_B — centered bottom */}
      <AbsoluteFill
        style={{
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "flex-end",
          paddingBottom: 320,
          opacity: phaseBOpacity,
          pointerEvents: "none",
        }}
      >
        <div style={{ display: "flex", gap: 36 }}>
          {USE_CHIPS_B.map((chip, i) => {
            const p = spring({ frame, fps, delay: 100 + i * 18, config: { damping: 200 } });
            return (
              <div
                key={i}
                style={{
                  display: "flex",
                  alignItems: "center",
                  gap: 20,
                  backgroundColor: `${chip.color}18`,
                  border: `2px solid ${chip.color}55`,
                  borderRadius: 60,
